## 4.2 实现配置合并

接下来，我们需要实现配置合并功能，我们在`src/core`目录下创建`mergeConfig.ts`文件。

```typescript
// src/core/mergeConfig.ts
import { AxiosRequestConfig } from "../types";
import { deepMerge, isPlainObject } from "../helpers/util";

const strats = Object.create(null);

function defaultStrat(val1: any, val2: any): any {
  return typeof val2 !== "undefined" ? val2 : val1;
}

function fromVal2Strat(val1: any, val2: any): any {
  if (typeof val2 !== "undefined") {
    return val2;
  }
}

function deepMergeStrat(val1: any, val2: any): any {
  if (isPlainObject(val2)) {
    return deepMerge(val1, val2);
  } else if (typeof val2 !== "undefined") {
    return val2;
  } else if (isPlainObject(val1)) {
    return deepMerge(val1);
  } else if (typeof val1 !== "undefined") {
    return val1;
  }
}

const stratKeysFromVal2 = ["url", "params", "data"];

stratKeysFromVal2.forEach((key) => {
  strats[key] = fromVal2Strat;
});

const stratKeysDeepMerge = ["headers", "auth"];

stratKeysDeepMerge.forEach((key) => {
  strats[key] = deepMergeStrat;
});

export default function mergeConfig(
  config1: AxiosRequestConfig,
  config2?: AxiosRequestConfig
): AxiosRequestConfig {
  if (!config2) {
    config2 = {};
  }

  const config = Object.create(null);

  for (let key in config2) {
    mergeField(key);
  }

  for (let key in config1) {
    if (!config2[key]) {
      mergeField(key);
    }
  }

  function mergeField(key: string): void {
    const strat = strats[key] || defaultStrat;
    config[key] = strat(config1[key], config2![key]);
  }

  return config;
}
```

代码说明：

1. 我们首先定义了三种合并策略：
   - `defaultStrat`：默认策略，如果`val2`有值则取`val2`，否则取`val1`；
   - `fromVal2Strat`：只取`val2`，如果`val2`没值，就不取；
   - `deepMergeStrat`：深度合并策略，如果`val2`是普通对象，则与`val1`进行深度合并，否则取`val2`，如果`val2`没值，则看`val1`，如果`val1`是普通对象，则返回`val1`的深拷贝，否则返回`val1`；
2. 然后，我们为不同的`key`指定不同的合并策略：
   - 对于`url`、`params`、`data`这三个属性，我们使用`fromVal2Strat`策略，即只取`config2`中的值；
   - 对于`headers`、`auth`这两个属性，我们使用`deepMergeStrat`策略，即深度合并；
   - 对于其他属性，我们使用`defaultStrat`策略；
3. 最后，我们遍历`config2`和`config1`的所有属性，使用对应的策略进行合并，并返回合并后的配置对象；

## 4.3 实现 create 接口

