```

我们新增了一个`mergeConfig`函数，用于合并默认配置和用户传入的配置。注意，这里我们使用浅拷贝的方式合并配置，即如果用户传入的配置中有和默认配置相同的属性，那么用户传入的配置会覆盖默认配置。

# 6. 修改 xhr 函数

由于我们修改了默认配置，所以在`xhr`函数中，我们需要使用合并后的配置。我们在`src/xhr.ts`中修改`xhr`函数。

```typescript
import { AxiosRequestConfig, AxiosPromise, AxiosResponse } from "./types";
import { parseHeaders } from "./helpers/headers";

export default function xhr(config: AxiosRequestConfig): AxiosPromise {
  return new Promise((resolve, reject) => {
    const {
      data = null,
      url,
      method = "get",
      headers,
      responseType,
      timeout,
    } = config;

    const request = new XMLHttpRequest();

    if (responseType) {
      request.responseType = responseType;
    }

    if (timeout) {
      request.timeout = timeout;
    }

    request.open(method.toUpperCase(), url, true);

    request.onreadystatechange = function handleLoad() {
      if (request.readyState !== 4) {
        return;
      }

      if (request.status === 0) {
        return;
      }

      const responseHeaders = parseHeaders(request.getAllResponseHeaders());
      const responseData =
        responseType && responseType !== "text"
          ? request.response
          : request.responseText;
      const response: AxiosResponse = {
        data: responseData,
        status: request.status,
        statusText: request.statusText,
        headers: responseHeaders,
        config,
        request,
      };
      resolve(response);
    };

    request.onerror = function handleError() {
      reject(new Error("Network Error"));
    };

    request.ontimeout = function handleTimeout() {
      reject(new Error(`Timeout of ${timeout} ms exceeded`));
    };

    Object.keys(headers).forEach((name) => {
      if (data === null && name.toLowerCase() === "content-type") {
        delete headers[name];
      } else {
        request.setRequestHeader(name, headers[name]);
      }
    });

    request.send(data);
  });
}
```

我们修改了`xhr`函数，从`config`中解构出`data`、`url`、`method`、`headers`、`responseType`、`timeout`等属性，并使用它们来设置`XMLHttpRequest`对象。

# 7. 修改拦截器

我们之前实现的拦截器是全局的，即所有的请求都会经过相同的拦截器。但是，我们现在希望用户可以在`config`中配置拦截器，即每个请求可以有自己的拦截器。所以我们需要修改拦截器的实现。

我们在`src/types/index.ts`中修改`AxiosRequestConfig`接口，添加`requestInterceptors`和`responseInterceptors`属性。

```typescript
export interface AxiosRequestConfig {
  url?: string;
  method?: Method;
  data?: any;
  params?: any;
  headers?: any;
  responseType?: XMLHttpRequestResponseType;
  timeout?: number;
  requestInterceptors?: AxiosInterceptorManager<AxiosRequestConfig>[];
  responseInterceptors?: AxiosInterceptorManager<AxiosResponse>[];
}
```

然后，我们在`src/axios.ts`中修改`axios`函数，在处理`config`时，将全局拦截器和`config`中配置的拦截器合并。

```typescript
import { AxiosRequestConfig, AxiosPromise } from "./types";
import xhr from "./xhr";
import { buildURL } from "./helpers/url";
import { transformRequest, transformResponse } from "./helpers/data";
import { processHeaders } from "./helpers/headers";
import defaults from "./defaults";
import {
  requestInterceptors,
  responseInterceptors,
} from "./interceptors";

function axios(config: AxiosRequestConfig): AxiosPromise;
function axios(url: string, config?: AxiosRequestConfig): AxiosPromise;
function axios(url: any, config?: any): AxiosPromise {
  if (typeof url === "string") {
    if (!config) {
      config = {};
    }
    config.url = url;
  } else {
    config = url;
  }

  // 合并配置
  config = mergeConfig(defaults, config);

  // 合并拦截器
  const mergedRequestInterceptors = [
    ...requestInterceptors,
    ...(config.requestInterceptors || []),
  ];
  const mergedResponseInterceptors = [
    ...responseInterceptors,
    ...(config.responseInterceptors || []),
  ];

  // 处理config
  config = processConfig(config);

  // 调用请求拦截器
  mergedRequestInterceptors.forEach((interceptor) => {
    config = interceptor(config);
  });

  // 调用xhr函数
  return xhr(config).then((response) => {
    // 调用响应拦截器
    mergedResponseInterceptors.forEach((interceptor) => {
      response = interceptor(response);
    });
    return response;
  });
}

// ... 其他代码不变
```

我们首先从`./interceptors`中导入全局的`requestInterceptors`和`responseInterceptors`，然后在处理`config`时，将全局拦截器和`config`中配置的拦截器合并。然后，我们在发送请求前，依次调用请求拦截器，在收到响应后，依次调用响应拦截器。

