    lastName: "Flintstone",
  },
});

// 只传config
axios({
  method: "post",
  url: "/user",
  data: {
    firstName: "Fred",
    lastName: "Flintstone",
  },
});

// 配置拦截器
axios({
  method: "post",
  url: "/user",
  data: {
    firstName: "Fred",
    lastName: "Flintstone",
  },
  requestInterceptors: [
    function (config) {
      console.log("request interceptor 1");
      return config;
    },
    function (config) {
      console.log("request interceptor 2");
      return config;
    },
  ],
  responseInterceptors: [
    function (response) {
      console.log("response interceptor 1");
      return response;
    },
    function (response) {
      console.log("response interceptor 2");
      return response;
    },
  ],
});
```

